import React from 'react';
import Column from './Column';
import { mockTasks } from '../data/mockData';

const Board = ({ onLogout }) => {
  const columns = [
    { id: 'todo', title: 'To Do', tasks: mockTasks.filter(t => t.status === 'todo') },
    { id: 'doing', title: 'Doing', tasks: mockTasks.filter(t => t.status === 'doing') },
    { id: 'done', title: 'Done', tasks: mockTasks.filter(t => t.status === 'done') },
  ];

  return (
    <div className="board-container">
      <div className="board-header">
        <h1>📋 <span>Sync</span>Board</h1>
        <button onClick={onLogout}>Logout</button>
      </div>
      <div className="board-columns">
        {columns.map(col => (
          <Column key={col.id} title={col.title} tasks={col.tasks} />
        ))}
      </div>
    </div>
  );
};

export default Board;
